// remote/public.ts — 对外 HTTPS 端点（vps 模式，复用 dsh-vps 的 Caddy）
//
// 引擎始终只监听 127.0.0.1；对外由 Caddy 在 dsh 已有的域名上另开一个端口转发：
//   https://<dsh 的域名>:9443/v1  → 127.0.0.1:8317
// 不能复用 443：dsh-gate 对所有路径（含 /api）都要求网页登录，只带 key 的 API 客户端过不去（实测）。
// 域名自动从 dsh-vps 的站点块读（/etc/caddy/dsh-site.conf 的第一个站点）；只有 IP 时用 <ip>.sslip.io，
// 这样仍能拿到正规证书。防火墙（iptables INPUT 默认 DROP）放行这个端口，并用一个开机服务保持；
// 关闭 / 卸载时全部撤销。
import { readFile, rm } from 'node:fs/promises';
import { isIP } from 'node:net';
import { run } from '../util/exec.js';
import { atomicWrite, exists } from '../util/fs.js';
import { DshModelError } from '../errors.js';
import { L } from '../i18n.js';
export const DSH_SITE_CONF = '/etc/caddy/dsh-site.conf';
export const DEFAULT_PUBLIC_PORT = 9443;
export const FIREWALL_UNIT = '/etc/systemd/system/dsh-model-firewall.service';
const FW_COMMENT = 'dsh-model';
/** dsh-vps 站点块的地址：域名，或 IP（没配域名时） */
export async function detectDshHost() {
    try {
        return parseSiteHost(await readFile(DSH_SITE_CONF, 'utf8'));
    }
    catch {
        return null;
    }
}
/** Caddyfile 片段里第一个站点块的地址 */
export function parseSiteHost(text) {
    for (const raw of text.split('\n')) {
        const line = raw.trim();
        if (!line || line.startsWith('#'))
            continue;
        const m = /^([^{}]+)\{$/.exec(line);
        if (!m)
            continue;
        // 站点地址可能是 "https://x"、"x:443"、"x, y"
        const first = m[1].trim().split(/[\s,]+/)[0].replace(/^https?:\/\//, '').replace(/:\d+$/, '');
        if (!first || first.startsWith('(') || first === 'import')
            continue;
        return { host: first, kind: isIP(first) ? 'ip' : 'domain' };
    }
    return null;
}
/** 本机公网 IPv4（从默认路由的源地址取） */
export async function publicIp() {
    const r = await run('ip', ['-4', 'route', 'get', '1.1.1.1']);
    const m = / src (\d+\.\d+\.\d+\.\d+)/.exec(r.stdout);
    return m?.[1] ?? null;
}
/** 有域名用域名；只有 IP 时用 <ip>.sslip.io（公共 DNS，解析回这个 IP），这样仍能签正规证书 */
export async function publicHost(override) {
    if (override)
        return override;
    const site = await detectDshHost();
    if (site?.kind === 'domain')
        return site.host;
    const ip = site?.kind === 'ip' ? site.host : await publicIp();
    if (!ip)
        throw new DshModelError('no_public_ip', L('查不到这台服务器的公网地址', 'Cannot determine the public address of this server'), L('用 --domain 指定：dsh-model remote enable --via caddy --domain 你的域名', 'Pass it explicitly: dsh-model remote enable --via caddy --domain your.domain'));
    return `${ip.replace(/\./g, '-')}.sslip.io`;
}
export function siteBlock(host, publicPort, enginePort) {
    return `# Generated by dsh-model. 由 dsh-model 生成：对外的 OpenAI 兼容端点（只认 dsh-model 的 key）\n${host}:${publicPort} {\n\treverse_proxy 127.0.0.1:${enginePort}\n}\n`;
}
async function ruleExists(bin, port) {
    return (await run(bin, ['-C', 'INPUT', '-p', 'tcp', '--dport', String(port), '-m', 'comment', '--comment', FW_COMMENT, '-j', 'ACCEPT'])).code === 0;
}
/** 放行端口（IPv4 + IPv6），并装一个开机时补回规则的 oneshot 服务 */
export async function openFirewall(port) {
    for (const bin of ['iptables', 'ip6tables']) {
        if (!(await ruleExists(bin, port)))
            await run(bin, ['-I', 'INPUT', '-p', 'tcp', '--dport', String(port), '-m', 'comment', '--comment', FW_COMMENT, '-j', 'ACCEPT']);
    }
    const add = (bin) => `/bin/sh -c '${bin} -C INPUT -p tcp --dport ${port} -m comment --comment ${FW_COMMENT} -j ACCEPT 2>/dev/null || ${bin} -I INPUT -p tcp --dport ${port} -m comment --comment ${FW_COMMENT} -j ACCEPT'`;
    const unit = [
        '# Generated by dsh-model. 由 dsh-model 生成：开机后放行对外端点的端口',
        '[Unit]',
        'Description=dsh-model public endpoint firewall rule',
        'After=network-online.target',
        '',
        '[Service]',
        'Type=oneshot',
        'RemainAfterExit=yes',
        `ExecStart=${add('iptables')}`,
        `ExecStart=${add('ip6tables')}`,
        '',
        '[Install]',
        'WantedBy=multi-user.target',
        '',
    ].join('\n');
    await atomicWrite(FIREWALL_UNIT, unit, { mode: 0o644 });
    await run('systemctl', ['daemon-reload']);
    await run('systemctl', ['enable', 'dsh-model-firewall.service']);
}
export async function closeFirewall(port) {
    for (const bin of ['iptables', 'ip6tables']) {
        while (await ruleExists(bin, port)) {
            const r = await run(bin, ['-D', 'INPUT', '-p', 'tcp', '--dport', String(port), '-m', 'comment', '--comment', FW_COMMENT, '-j', 'ACCEPT']);
            if (r.code !== 0)
                break;
        }
    }
    if (await exists(FIREWALL_UNIT)) {
        await run('systemctl', ['disable', 'dsh-model-firewall.service']);
        await rm(FIREWALL_UNIT, { force: true });
        await run('systemctl', ['daemon-reload']);
    }
}
